function areaControls(api){
  U.editor(api,{...Areas,title:'Allowed color area',prepare:true,help:'Drag a color point to adjust it. Drag the rectangle body to move it, or its top-right corner to resize it. Colors stay put until an edge reaches them. Triangle boundaries clip the area. Book restrictions are paused.',
    fields(f){const c=f.config;
      f.select('shape','Custom shape',()=>c.shape,[['rectangle','Rectangle'],['polygon','Polygon']],v=>c.shape=v);
      if(c.shape==='rectangle')for(const [i,label]of ['Left X','Bottom Y','Width','Height'].entries())f.number('rect-'+i,label,()=>c.rect[i],v=>c.rect[i]=v,i<2?0:Areas.minimum,()=>i<2?1-c.rect[i+2]:1-c.rect[i-2],.1);
      else{f.text('vertices','Vertices [X, Y], from 0 to 1',()=>JSON.stringify(c.polygon),v=>{const p=JSON.parse(v);G.polygon(p,32);c.polygon=p;});f.action('add-vertex','Add vertex',()=>{if(c.polygon.length>=32)throw Error('Maximum 32 vertices.');let best=0;for(let i=1;i<c.polygon.length;i++)if(Math.hypot(...G.sub(c.polygon[i],c.polygon[(i+1)%c.polygon.length]))>Math.hypot(...G.sub(c.polygon[best],c.polygon[(best+1)%c.polygon.length])))best=i;c.polygon.splice(best+1,0,G.mul(G.add(c.polygon[best],c.polygon[(best+1)%c.polygon.length]),.5));});f.action('remove-vertex','Remove last vertex',()=>{if(c.polygon.length>3)c.polygon.pop();});}
      f.note('Apply the area to these colors (unchecked colors are exceptions):');
      for(const id of U.roles(f.ball))f.check('role-'+id,E.roleName(f.ball,id),()=>c.roles.includes(id),on=>{c.roles=c.roles.filter(x=>x!==id);if(on)c.roles.push(id);});
    },
    beginDrag(c,start){if(!c.visible)return null;if(c.shape==='rectangle'){if(Math.hypot(...G.sub(start,[c.rect[0]+c.rect[2],c.rect[1]+c.rect[3]]))<.06)return 'resize';return G.inside(start,Areas.rectangle(c))?'move':null;}const i=c.polygon.findIndex(p=>Math.hypot(...G.sub(p,start))<.06);return i<0?null:{vertex:i};},
    dragOrigin(c,action){return c.shape==='rectangle'?[c.rect[0]+c.rect[2]*(action==='resize'?1:.5),c.rect[1]+c.rect[3]*(action==='resize'?1:.5)]:c.polygon[action.vertex];},
    drag(c,d,action){const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));if(c.shape==='rectangle'){if(action==='resize'){c.rect[2]=clamp(c.rect[2]+d[0],Areas.minimum,1-c.rect[0]);c.rect[3]=clamp(c.rect[3]+d[1],Areas.minimum,1-c.rect[1]);}else{c.rect[0]=clamp(c.rect[0]+d[0],0,1-c.rect[2]);c.rect[1]=clamp(c.rect[1]+d[1],0,1-c.rect[3]);}}else c.polygon[action.vertex]=G.add(c.polygon[action.vertex],d).map(v=>clamp(v,0,1));return c;}
  });
  const legend=U.make('p',{id:'color-areas-membership',class:'hint'});api.mount('tools').append(legend);api.onCleanup(Areas.clear);
  api.subscribe(state=>{const b=state.project.balls.find(b=>b.id===state.activeBallId),shape=state.project.pickerShape||'triangle',c=S.get(b,'color-areas',shape);if(!c){legend.textContent='';return;}if(!Areas.effective(c)){legend.textContent='Saved book restrictions are paused. Edit to create a custom area.';return;}try{Areas.check(c,b);const colors=E.resolve(b);legend.textContent=(c.mode==='both'?'Book portion paused; custom area only. ':'')+c.roles.map(id=>E.roleName(b,id)+': '+(S.restrictions({provider:Areas,config:c},id,colors[id][0],shape).every(poly=>G.inside(G.point(colors[id],shape),poly))?'in':'out')).join(' · ');}catch(failure){legend.textContent='Suspended · '+failure.message;}});
}
